package cn.yuanxin.mvp.web.config;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;

import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * {@link NonProductionCondition} 纯单元测试（{@link MockEnvironment}，无 Spring 上下文、
 * 不连库）：锁定“环境 profile”与“实现选择”解耦后的非生产判据。
 */
class NonProductionConditionTest {

    /** 显式 active profiles。 */
    private static MockEnvironment active(String appEnv, String... activeProfiles) {
        MockEnvironment environment = new MockEnvironment();
        if (appEnv != null) {
            environment.setProperty("app.env", appEnv);
        }
        environment.setActiveProfiles(activeProfiles);
        return environment;
    }

    /** 无显式 active profile；default profiles 模拟 application.yml 的 {@code dev}。 */
    private static MockEnvironment defaultOnly(String appEnv, String... defaultProfiles) {
        MockEnvironment environment = new MockEnvironment();
        if (appEnv != null) {
            environment.setProperty("app.env", appEnv);
        }
        environment.setDefaultProfiles(defaultProfiles);
        return environment;
    }

    // ---------- 放行：任何非生产环境名 ----------

    @Test
    @DisplayName("local/dev/test 环境放行")
    void localDevTestAreNonProduction() {
        assertTrue(NonProductionCondition.isNonProduction(active("dev", "local")));
        assertTrue(NonProductionCondition.isNonProduction(active("dev", "dev")));
        assertTrue(NonProductionCondition.isNonProduction(active("test", "test")));
    }

    @Test
    @DisplayName("无显式 profile（default=dev）放行")
    void defaultDevProfileIsNonProduction() {
        assertTrue(NonProductionCondition.isNonProduction(defaultOnly(null, "dev")));
    }

    @Test
    @DisplayName("app.env 缺省（默认 dev）放行")
    void missingAppEnvDefaultsToDev() {
        assertTrue(NonProductionCondition.isNonProduction(active(null, "local")));
    }

    @Test
    @DisplayName("自定义环境名（staging/anything）放行——不要求 dev/test")
    void customEnvironmentNamesAreNonProduction() {
        assertTrue(NonProductionCondition.isNonProduction(active("staging", "staging")));
        assertTrue(NonProductionCondition.isNonProduction(active("qa", "anything")));
    }

    // ---------- 拒绝：生产 env / prod profile / 混合 ----------

    @Test
    @DisplayName("prod / production profile 拒绝")
    void prodProfilesAreProduction() {
        assertFalse(NonProductionCondition.isNonProduction(active("dev", "prod")));
        assertFalse(NonProductionCondition.isNonProduction(active("dev", "production")));
    }

    @Test
    @DisplayName("混合 prod,dev 与 dev,prod 均拒绝（不因含 dev 而放行）")
    void mixedProdDevProfilesAreProduction() {
        assertFalse(NonProductionCondition.isNonProduction(active("dev", "prod", "dev")));
        assertFalse(NonProductionCondition.isNonProduction(active("dev", "dev", "prod")));
    }

    @Test
    @DisplayName("app.env=production + dev profile 拒绝（env 判据独立生效）")
    void productionEnvWithDevProfileIsProduction() {
        assertFalse(NonProductionCondition.isNonProduction(active("production", "dev")));
    }

    @Test
    @DisplayName("app.env=' Production '（大小写/空白）拒绝")
    void productionEnvCaseInsensitiveAndTrimmed() {
        assertFalse(NonProductionCondition.isNonProduction(active(" Production ", "local")));
    }

    @Test
    @DisplayName("app.env=dev + prod profile 拒绝（profile 判据独立生效）")
    void prodProfileWithDevEnvIsProduction() {
        assertFalse(NonProductionCondition.isNonProduction(active("dev", "prod")));
    }

    // ---------- effectiveProfiles 语义 ----------

    @Test
    @DisplayName("effectiveProfiles：active 非空时优先，忽略 default")
    void effectiveProfilesPreferActive() {
        MockEnvironment environment = defaultOnly(null, "prod");
        environment.setActiveProfiles("local");
        assertEquals(Set.of("local"), NonProductionCondition.effectiveProfiles(environment));
        assertTrue(NonProductionCondition.isNonProduction(environment));
    }

    @Test
    @DisplayName("effectiveProfiles：active 为空则取 default，统一小写")
    void effectiveProfilesFallBackToDefault() {
        MockEnvironment environment = defaultOnly(null, "Dev", "TEST");
        assertEquals(Set.of("dev", "test"), NonProductionCondition.effectiveProfiles(environment));
    }

    @Test
    @DisplayName("effectiveProfiles：active 统一小写（PROD → prod）")
    void effectiveProfilesLowercase() {
        MockEnvironment environment = active("dev", "PROD");
        assertEquals(Set.of("prod"), NonProductionCondition.effectiveProfiles(environment));
        assertFalse(NonProductionCondition.isNonProduction(environment));
    }
}

package cn.yuanxin.mvp.web.config;

import cn.yuanxin.mvp.web.media.StoragePort;
import cn.yuanxin.mvp.web.testdouble.FileSystemStorageDouble;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.NoSuchBeanDefinitionException;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * SC-C-05 存储失败注入缝的生产 fail-closed（双判据，对齐 DocsProductionGuard）：
 * 只要出现生产信号——激活 profile 含 {@code prod} <b>或</b> {@code app.env=production}
 * ——{@link TestDoubleProvidersConfig} 就拒绝装配，使
 * {@code APP_DOUBLE_STORAGE_FAIL_MODE} 在混合 profile（prod,dev）与矛盾组合
 * （prod profile + app.env=dev，即便显式 mode=doubles）下均不可达；纯 prod profile
 * 下配置根本不激活（替身不被装配）。本类为隔离上下文 runner，不启动 web 服务器；
 * 真实进程"端口未绑定"证据见交付报告。
 *
 * <p><b>本轮机制变化（环境/实现解耦）：</b>此前 {@code TestDoubleProvidersConfig} 用
 * {@code @Profile(\{"dev","test"\})} 门，混合 {@code prod,dev} 因含 {@code dev} 而照常装配，
 * 再由 {@code storagePort()} 内 {@code requireNoProductionSignals} 在 <em>@Bean 装配期</em>
 * 抛 {@link IllegalStateException} 拒绝（根因是守卫异常）。解耦后替身配置改用共享
 * {@link NonProductionCondition}（{@code app.env != production} 且生效 profiles 不含
 * prod/production），<b>拒装在条件层提前发生</b>：混合 prod,dev 或 {@code app.env=production}
 * 时整个配置根本不装配，{@code StoragePort} 替身从不被构造（安全属性增强，非弱化）。</p>
 *
 * <p>因此本类对"生产信号"用例的断言随之改为：需要 {@code StoragePort} 的应用组件在
 * 启动时因 <b>缺 bean</b>（{@link NoSuchBeanDefinitionException}）失败，且失败消息中
 * <b>绝不出现</b> {@code FileSystemStorageDouble} / {@code APP_DOUBLE_STORAGE_FAIL_MODE}
 * ——直接证明替身未构造、注入开关不可达。断言强度不降：仍锁定失败信号、失败根因、
 * 开关不可达三点。</p>
 */
class StorageFailModeProductionFailClosedTest {

    @Configuration
    @EnableConfigurationProperties(AppProperties.class)
    static class PropsConfig {
    }

    @Configuration
    static class JdbcConfig {
        @Bean
        JdbcTemplate jdbcTemplate() {
            // 本类只验证装配/fail-closed，不访问 DB；替身仅持有引用。
            return org.mockito.Mockito.mock(JdbcTemplate.class);
        }
    }

    /** 代表"应用真实需要 StoragePort"的消费者，用于把"替身未装配"暴露为启动失败。 */
    record StoragePortConsumer(StoragePort storagePort) {
    }

    @Configuration
    static class StoragePortConsumerConfig {
        @Bean
        StoragePortConsumer storagePortConsumer(StoragePort storagePort) {
            return new StoragePortConsumer(storagePort);
        }
    }

    private static ApplicationContextRunner runner(String... profiles) {
        return new ApplicationContextRunner()
                .withUserConfiguration(PropsConfig.class, JdbcConfig.class,
                        TestDoubleProvidersConfig.class)
                .withInitializer(ctx -> ctx.getEnvironment().setActiveProfiles(profiles));
    }

    /** 追加依赖 StoragePort 的消费者：替身被拒装 ⇒ 消费者无法创建 ⇒ 上下文启动失败。 */
    private static ApplicationContextRunner runnerRequiringStoragePort(String... profiles) {
        return new ApplicationContextRunner()
                .withUserConfiguration(PropsConfig.class, JdbcConfig.class,
                        TestDoubleProvidersConfig.class, StoragePortConsumerConfig.class)
                .withInitializer(ctx -> ctx.getEnvironment().setActiveProfiles(profiles));
    }

    @Test
    @DisplayName("app.env=production + test profile + fail-put → 启动失败（替身拒装，开关不可达）")
    void productionEnvFailsClosed() {
        runnerRequiringStoragePort("test")
                .withPropertyValues("app.env=production",
                        "APP_DOUBLE_STORAGE_FAIL_MODE=fail-put")
                .run(ctx -> {
                    assertThat(ctx).hasFailed();
                    // 拒装提前到条件层：根因是缺 StoragePort bean（而非守卫异常）。
                    assertThat(ctx.getStartupFailure())
                            .hasRootCauseInstanceOf(NoSuchBeanDefinitionException.class)
                            .hasRootCauseMessage("No qualifying bean of type"
                                    + " 'cn.yuanxin.mvp.web.media.StoragePort' available")
                            // 替身从未构造、注入开关从未被读取。
                            .hasMessageNotContaining("FileSystemStorageDouble")
                            .hasMessageNotContaining("APP_DOUBLE_STORAGE_FAIL_MODE");
                });
    }

    @Test
    @DisplayName("混合 profile (prod,dev) + app.env=dev + mode=doubles + fail-put → 启动失败（profile 判据）")
    void mixedProdDevProfileFailsClosed() {
        runnerRequiringStoragePort("prod", "dev")
                .withPropertyValues("app.env=dev", "app.providers.mode=doubles",
                        "APP_DOUBLE_STORAGE_FAIL_MODE=fail-put")
                .run(ctx -> {
                    assertThat(ctx).hasFailed();
                    assertThat(ctx.getStartupFailure())
                            .hasRootCauseInstanceOf(NoSuchBeanDefinitionException.class)
                            .hasMessageNotContaining("FileSystemStorageDouble")
                            .hasMessageNotContaining("APP_DOUBLE_STORAGE_FAIL_MODE");
                });
    }

    @Test
    @DisplayName("app.env 大小写/空白容错：' Production ' 亦判生产信号（对齐 DocsProductionGuard）")
    void productionEnvCaseInsensitiveAndTrimmed() {
        runnerRequiringStoragePort("test")
                .withPropertyValues("app.env= Production ",
                        "app.storage.dev-dir=target/storage-it/prod-guard-case",
                        "APP_DOUBLE_STORAGE_FAIL_MODE=fail-put")
                .run(ctx -> {
                    assertThat(ctx).hasFailed();
                    assertThat(ctx.getStartupFailure())
                            .hasRootCauseInstanceOf(NoSuchBeanDefinitionException.class)
                            .hasMessageNotContaining("FileSystemStorageDouble")
                            .hasMessageNotContaining("APP_DOUBLE_STORAGE_FAIL_MODE");
                });
    }

    @Test
    @DisplayName("纯 prod profile → 替身配置不激活，绝不装配 StoragePort 替身")
    void prodProfileNeverAssemblesDouble() {
        runner("prod")
                .withPropertyValues("app.providers.mode=doubles")
                .run(ctx -> {
                    assertThat(ctx).hasNotFailed();
                    assertThat(ctx.getBeansOfType(StoragePort.class)).isEmpty();
                });
