```java
public class ProvidersModeProductionGuard implements BeanFactoryPostProcessor, EnvironmentAware {
    private Environment environment;
    @Override public void setEnvironment(Environment environment) { this.environment = environment; }
    @Override public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) {
        if (NonProductionCondition.isNonProduction(environment)) return;
        String mode = new AppProperties.Providers(environment.getProperty("app.providers.mode")).mode();
        if (!"doubles".equals(mode)) return;
        Set<String> profiles = NonProductionCondition.effectiveProfiles(environment);
        String appEnv = environment.getProperty("app.env", "dev");
        throw new IllegalStateException("production fail-closed: app.providers.mode=doubles is not allowed"
            + " under production signals (active-profiles=" + profiles + ", app.env=" + appEnv
            + "); configure app.providers.mode=real with production implementations, or app.providers.mode=disabled to explicitly disable capabilities");
    }
}
```

