package cn.yuanxin.mvp.web.face;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * InsightFace 人脸服务配置（{@code app.face.insightface.*}）。<b>默认值写在代码里</b>。
 *
 * <p>示例 base-url（内网，仅文档示例、非默认值）：{@code http://10.3.6.163:8010}。</p>
 *
 * <p><b>安全：</b>缺失校验只输出<b>键名</b>；{@link #toString()} 与异常消息绝不回显 token。
 * token 推荐用 {@code internal-token-file}（根在部署机放置，仅进程可读）。</p>
 *
 * <p>read 超时默认 30s：远端模型首次加载/CPU 推理较慢，超时过短会误判依赖失败。</p>
 */
@ConfigurationProperties(prefix = "app.face.insightface")
public record InsightFaceProperties(
        String baseUrl,
        String namespace,
        String internalToken,
        String internalTokenFile,
        Integer connectTimeoutMillis,
        Integer readTimeoutMillis,
        Double verifyThreshold) {

    public static final int DEFAULT_CONNECT_TIMEOUT_MILLIS = 3000;
    public static final int DEFAULT_READ_TIMEOUT_MILLIS = 30000;
    public static final int MIN_TIMEOUT_MILLIS = 1000;

    public InsightFaceProperties {
        baseUrl = trimToNull(baseUrl);
        namespace = trimToNull(namespace);
        internalToken = trimToNull(internalToken);
        internalTokenFile = trimToNull(internalTokenFile);
        connectTimeoutMillis = normalizeTimeout(connectTimeoutMillis, DEFAULT_CONNECT_TIMEOUT_MILLIS);
        readTimeoutMillis = normalizeTimeout(readTimeoutMillis, DEFAULT_READ_TIMEOUT_MILLIS);
    }

    /** 缺失的必填键（仅键名）。token 二选一：两者皆无时列为缺失。 */
    public List<String> missingRequiredKeys() {
        List<String> missing = new ArrayList<>();
        if (baseUrl == null) {
            missing.add("app.face.insightface.base-url");
        }
        if (namespace == null) {
            missing.add("app.face.insightface.namespace");
        }
        if (internalToken == null && internalTokenFile == null) {
            missing.add("app.face.insightface.internal-token or app.face.insightface.internal-token-file");
        }
        return missing;
    }

    /** 两种 token 来源同时配置 → 拒绝启动（配置歧义）。 */
    public boolean tokenSourcesConflict() {
        return internalToken != null && internalTokenFile != null;
    }

    /** 解析 token（内联优先；否则读文件）。绝不把值写入日志/消息。 */
    public String resolvedToken() {
        if (internalToken != null) {
            return internalToken;
        }
        if (internalTokenFile == null) {
            return null;
        }
        try {
            String value = Files.readString(Path.of(internalTokenFile), StandardCharsets.UTF_8).trim();
            if (value.isEmpty()) {
                throw new IllegalStateException(
                        "app.face.insightface.internal-token-file is empty; provide a token (value not logged)");
            }
            return value;
        } catch (IOException unreadable) {
            throw new IllegalStateException("app.face.insightface.internal-token-file could not be read"
                    + " (path not logged); provide a readable token file");
        }
    }

    @Override
    public String toString() {
        return "InsightFaceProperties[baseUrl=" + baseUrl + ", namespace=" + namespace
                + ", internalToken=" + (internalToken == null ? "<absent>" : "<redacted>")
                + ", internalTokenFile=" + (internalTokenFile == null ? "<absent>" : "<set>")
                + ", connectTimeoutMillis=" + connectTimeoutMillis
                + ", readTimeoutMillis=" + readTimeoutMillis
                + ", verifyThreshold=" + verifyThreshold + "]";
    }

    private static Integer normalizeTimeout(Integer value, int fallback) {
        int normalized = value == null || value <= 0 ? fallback : value;
        return Math.max(MIN_TIMEOUT_MILLIS, normalized);
    }

    private static String trimToNull(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }
}

package cn.yuanxin.mvp.web.face;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 阿里云人脸 provider 的<b>配置边界</b>（{@code app.face.aliyun.*}）——<b>仅键名与类型</b>，
 * 不含任何实现。{@code app.face.provider=aliyun} 会在启动期被
 * {@link AliyunFaceBoundaryConfig} 明确拒绝（未实现），绝不静默回退 doubles、绝不臆造能力。
 *
 * <p>字段仅用于表达将要接入的配置面；{@link #toString()} 脱敏。</p>
 */
@ConfigurationProperties(prefix = "app.face.aliyun")
public record AliyunFaceProperties(
        String region,
        String endpoint,
        String accessKeyId,
        String accessKeySecret,
        String securityToken,
        String serviceName) {

    @Override
    public String toString() {
        return "AliyunFaceProperties[region=" + region + ", endpoint=" + endpoint
                + ", accessKeyId=" + redacted(accessKeyId)
                + ", accessKeySecret=" + redacted(accessKeySecret)
                + ", securityToken=" + redacted(securityToken)
                + ", serviceName=" + serviceName + "]";
    }

    private static String redacted(String value) {
        return value == null ? "<absent>" : "<redacted>";
    }
}

package cn.yuanxin.mvp.web.face;

/**
 * 远端人脸服务错误信封中的错误信息（{@code {"error":{...}}}）。
 *
 * @param code      服务错误码（如 {@code NO_FACE}/{@code SUBJECT_NOT_FOUND}）
 * @param message   服务消息（不含我方 token/图像；可安全记录）
 * @param retryable 服务声明的可重试性
 * @param requestId 服务请求 id（诊断用）
 * @param httpStatus HTTP 状态码（本地捕获）
 */
public record FaceServiceError(
        String code,
        String message,
        boolean retryable,
        String requestId,
        int httpStatus) {

    public String safeCode() {
        return code == null || code.isBlank() ? "<none>" : code;
    }
}

package cn.yuanxin.mvp.web.face;

import java.util.Set;

/**
 * 人脸服务失败分类：把 HTTP 状态 + 服务错误码映射为
 * 配置错误（不可重试）/ 能力不可用 / 依赖故障（可重试）。
 *
 * <p>质量类码（{@code NO_FACE}/{@code MULTI_FACES_AMBIGUOUS}/{@code IMAGE_DECODE_FAILED}/
 * {@code QUALITY_INSUFFICIENT}）由适配器<b>先于</b>本分类识别为图像质量问题，不在这里归为
 * 配置错误。</p>
 */
public enum FaceServiceFailureKind {

    CONFIGURATION,
    CAPABILITY,
    DEPENDENCY;

    static final Set<String> CAPABILITY_CODES = Set.of(
            "SUBJECT_NOT_FOUND",
            "NAMESPACE_NOT_FOUND",
            "LIVENESS_UNSUPPORTED");

    static final Set<String> CONFIGURATION_CODES = Set.of(
            "UNAUTHORIZED",
            "UNSUPPORTED_MEDIA_TYPE",
            "IMAGE_TOO_LARGE",
            "INVALID_REQUEST",
            "SUBJECT_ALREADY_EXISTS");

    static final Set<String> DEPENDENCY_CODES = Set.of(
            "MODEL_UNAVAILABLE",
            "MODEL_NOT_LOADED",
            "CONCURRENCY_LIMIT",
            "INFERENCE_TIMEOUT",
            "INTERNAL_ERROR");

    public static FaceServiceFailureKind classify(int httpStatus, String code) {
        String normalized = code == null ? "" : code.trim();
        if (CAPABILITY_CODES.contains(normalized)) {
            return CAPABILITY;
        }
        if (CONFIGURATION_CODES.contains(normalized)) {
            return CONFIGURATION;
        }
        if (DEPENDENCY_CODES.contains(normalized)) {
            return DEPENDENCY;
        }
        if (httpStatus == 401 || httpStatus == 413 || httpStatus == 415) {
            return CONFIGURATION;
        }
        if (httpStatus == 404 || httpStatus == 409 || httpStatus == 422 || httpStatus == 501) {
            return CAPABILITY;
        }
        if (httpStatus == 429 || httpStatus >= 500) {
            return DEPENDENCY;
        }
        if (httpStatus == 400) {
            // 其余 400 视为参数/配置问题（质量类码已被适配器提前识别）。
            return CONFIGURATION;
        }
        return DEPENDENCY;
    }
}

