import cn.yuanxin.mvp.web.care.CareFaceVerifier;
import cn.yuanxin.mvp.web.config.NonProductionCondition;
import cn.yuanxin.mvp.web.identity.FaceIdentityResolver;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.List;

/**
 * InsightFace 人脸装配（B 自有）：仅当 {@code app.face.provider=insightface} <b>且</b>
 * {@code app.providers.mode != disabled} 时激活。
 *
 * <p><b>启动期校验</b>：缺 {@code base-url}/{@code namespace}/token（二选一皆无）⇒ 拒绝启动，
 * 消息只列缺失键名；内联 token 与 token 文件同时配置 ⇒ 拒绝启动（歧义）。<b>不调用远端服务
 * 校验配置</b>（避免启动期网络依赖与副作用）。</p>
 *
 * <p><b>装配</b>：{@link InsightFaceProvider}（FaceProvider，真实；可生产）、
 * {@link UnavailableFaceIdentityResolver}（红线 2：身份解析未接入，恒 empty）、
 * {@link InsightFaceCareVerifier}（{@code @Primary}；<b>非生产条件</b>——生产信号下不装配，
 * 由无条件 {@code FailClosedCareFaceVerifier} 接管，避免与
 * {@code CareFaceVerifierProductionGuard} 冲突；守卫未改）。</p>
 *
 * <p>{@code mode=disabled} 时本配置整体不激活，走 A 的 disabled 占位。</p>
 */
@Configuration
@ConditionalOnProperty(name = "app.face.provider", havingValue = "insightface")
@Conditional(FaceProviderEnabledCondition.class)
@EnableConfigurationProperties({InsightFaceProperties.class, AliyunFaceProperties.class})
public class FaceProvidersConfig {

    @Bean
    public FaceServiceClient faceServiceClient(InsightFaceProperties properties,
                                               ObjectMapper objectMapper) {
        List<String> missing = properties.missingRequiredKeys();
        if (!missing.isEmpty()) {
            throw new IllegalStateException("app.face.provider=insightface missing required config keys: "
                    + missing + " (values are never logged)");
        }
        if (properties.tokenSourcesConflict()) {
            throw new IllegalStateException("app.face.provider=insightface requires exactly one of"
                    + " internal-token / internal-token-file (both are set)");
        }
        return new FaceServiceClient(properties, objectMapper);
    }

    @Bean
    public FaceProvider insightFaceProvider(FaceServiceClient faceServiceClient) {
        return new InsightFaceProvider(faceServiceClient);
    }

    @Bean
    public FaceIdentityResolver unavailableFaceIdentityResolver(InsightFaceProperties properties) {
        return new UnavailableFaceIdentityResolver(properties.namespace());
    }

    /** 非生产条件：生产信号下不装配，避免与 {@code CareFaceVerifierProductionGuard} 冲突。 */
    @Bean
    @Conditional(NonProductionCondition.class)
    @Primary
    public CareFaceVerifier insightFaceCareVerifier(FaceServiceClient faceServiceClient,
                                                    JdbcTemplate jdbc,
                                                    InsightFaceProperties properties) {
        return new InsightFaceCareVerifier(faceServiceClient, jdbc, properties.verifyThreshold());
    }
}

package cn.yuanxin.mvp.web.face;

import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Conditional;
import org.springframework.context.annotation.Configuration;

/**
 * {@code app.face.provider=aliyun} 的<b>启动期拒绝</b>（红线 3）。
 *
 * <p>阿里云人脸 provider 目前<b>只有配置边界</b>（{@link AliyunFaceProperties}），<b>没有实现</b>。
 * 选择它必须拒绝启动并给出明确诊断，<b>绝不</b>静默回退 doubles、<b>绝不</b>提供假实现；
 * 也<b>不臆造</b>任何阿里云人脸 API 调用。</p>
 *
 * <p>{@code mode=disabled} 时本配置不激活（{@link FaceProviderEnabledCondition}）——能力显式
 * 关闭优先，走 A 的 disabled 占位。</p>
 */
@Configuration
@ConditionalOnProperty(name = "app.face.provider", havingValue = "aliyun")
@Conditional(FaceProviderEnabledCondition.class)
public class AliyunFaceBoundaryConfig {

    @Bean
    public Object aliyunFaceBoundary() {
        // 只说明事实与可选项；不回显任何配置值。
        throw new IllegalStateException("app.face.provider=aliyun is not implemented: only a configuration"
                + " boundary (app.face.aliyun.*) exists; use app.face.provider=doubles or insightface");
    }
}

package cn.yuanxin.mvp.web.face;

import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * InsightFace 服务的本地 HTTP stub（随机端口；测试用，不发真实人脸、不访问真实服务）。
 * 记录方法/路径/内部 token 头/原始 body，供 wire 与脱敏断言。
 */
final class FaceServiceStub implements AutoCloseable {

    record Request(String method, String path, String internalToken, byte[] body) {
    }

    private final List<Request> requests = new CopyOnWriteArrayList<>();
    private volatile int healthStatus = 200;
    private volatile String healthBody =
            "{\"status\":\"ok\",\"model_loaded\":true,\"model_version\":\"buffalo_l@fake\","
                    + "\"liveness\":{\"supported\":false,\"reason\":\"no liveness model\"}}";
    private volatile int extractStatus = 200;
    private volatile String extractBody = "{\"face_count\":1,\"request_id\":\"req-extract\"}";
    private volatile int verifyStatus = 200;
    private volatile String verifyBody =
            "{\"matched\":true,\"similarity\":0.9,\"threshold\":0.4,\"request_id\":\"req-verify\"}";
    private volatile long delayMillis = 0;

    private HttpServer server;

    void start() throws IOException {
        server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.createContext("/", this::handle);
        server.start();
    }

    String baseUrl() {
        return "http://127.0.0.1:" + server.getAddress().getPort();
    }

    void health(int status, String body) {
        this.healthStatus = status;
        this.healthBody = body;
    }

    void extract(int status, String body) {
        this.extractStatus = status;
        this.extractBody = body;
    }

    void verify(int status, String body) {
        this.verifyStatus = status;
        this.verifyBody = body;
    }

    void delay(long millis) {
        this.delayMillis = millis;
    }

    List<Request> requests() {
        return requests;
    }

    Request last(String method, String pathSuffix) {
        for (int i = requests.size() - 1; i >= 0; i--) {
            Request r = requests.get(i);
            if (r.method().equalsIgnoreCase(method) && r.path().endsWith(pathSuffix)) {
                return r;
            }
        }
        return null;
    }

    private void handle(HttpExchange exchange) throws IOException {
        byte[] body = exchange.getRequestBody().readAllBytes();
        requests.add(new Request(exchange.getRequestMethod(), exchange.getRequestURI().getPath(),
                exchange.getRequestHeaders().getFirst("X-Internal-Token"), body));
        if (delayMillis > 0) {
            try {
                Thread.sleep(delayMillis);
            } catch (InterruptedException interrupted) {
                Thread.currentThread().interrupt();
            }
        }
        String path = exchange.getRequestURI().getPath();
        int status;
        String response;
        if (path.endsWith("/v1/health")) {
            status = healthStatus;
            response = healthBody;
        } else if (path.endsWith("/v1/extract")) {
            status = extractStatus;
            response = extractBody;
        } else if (path.endsWith("/v1/verify")) {
            status = verifyStatus;
            response = verifyBody;
        } else {
            status = 404;
            response = "{\"error\":{\"code\":\"NOT_FOUND\",\"message\":\"unknown\",\"retryable\":false}}";
        }
        byte[] bytes = response.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(status, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }

    @Override
    public void close() {
        if (server != null) {
            server.stop(0);
        }
    }

    static String errorBody(String code, boolean retryable, String requestId) {
        return "{\"error\":{\"code\":\"" + code + "\",\"message\":\"stub " + code
                + "\",\"retryable\":" + retryable + ",\"request_id\":\"" + requestId + "\"}}";
    }
}

package cn.yuanxin.mvp.web.face;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** {@link FaceServiceClient} 的本地 stub 测试（不发真实人脸、不访问真实服务）。 */
class FaceServiceClientTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-image-bytes".getBytes(StandardCharsets.UTF_8);
    private static final String FAKE_TOKEN = "FAKE-INTERNAL-TOKEN-DO-NOT-USE";

    private FaceServiceStub stub;
    private FaceServiceClient client;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        client = new FaceServiceClient(properties(stub.baseUrl(), 1500, 1500), new ObjectMapper());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    private static InsightFaceProperties properties(String baseUrl, int connect, int read) {
        return new InsightFaceProperties(baseUrl, "openvela-mvp", FAKE_TOKEN, null, connect, read, null);
    }

    @Test
    @DisplayName("health 解析公开端点（liveness.supported=false）")
    void healthParsed() {
        FaceServiceClient.Health health = client.health();
        assertThat(health.ok()).isTrue();
        assertThat(health.modelLoaded()).isTrue();
        assertThat(health.livenessSupported()).isFalse();
    }

    @Test
    @DisplayName("extract 成功返回 face_count；内部 token 随请求发送")
    void extractSuccessAndTokenHeader() {
        FaceServiceClient.ExtractResult result = client.extract(SYNTHETIC_IMAGE);
        assertThat(result.faceCount()).isEqualTo(1);
        assertThat(stub.last("POST", "/v1/extract").internalToken()).isEqualTo(FAKE_TOKEN);
    }

    @Test
    @DisplayName("NO_FACE(400) → 抛异常并携带服务码（不静默成功）")
    void noFaceThrows() {
        stub.extract(400, FaceServiceStub.errorBody("NO_FACE", false, "r-noface"));
        assertThatThrownBy(() -> client.extract(SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> {
                    FaceServiceException e = (FaceServiceException) thrown;
                    assertThat(e.error().code()).isEqualTo("NO_FACE");
                    assertThat(e.error().httpStatus()).isEqualTo(400);
                });
    }

    @Test
    @DisplayName("SUBJECT_NOT_FOUND(404) → CAPABILITY")
    void subjectNotFoundIsCapability() {
        stub.verify(404, FaceServiceStub.errorBody("SUBJECT_NOT_FOUND", false, "r-sub"));
        assertThatThrownBy(() -> client.verify(SYNTHETIC_IMAGE, "openvela-mvp", "sub-1", null))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.CAPABILITY));
    }

    @Test
    @DisplayName("MODEL_UNAVAILABLE(503) → DEPENDENCY")
    void serviceUnavailableIsDependency() {
        stub.extract(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r-model"));
        assertThatThrownBy(() -> client.extract(SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.DEPENDENCY));
    }

    @Test
    @DisplayName("UNAUTHORIZED(401) → CONFIGURATION")
    void unauthorizedIsConfiguration() {
        stub.extract(401, FaceServiceStub.errorBody("UNAUTHORIZED", false, "r-auth"));
        assertThatThrownBy(() -> client.extract(SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.CONFIGURATION));
    }

    @Test
    @DisplayName("读取超时 → DEPENDENCY（不静默成功）")
    void timeoutIsDependency() {
        stub.delay(1600);
        FaceServiceClient slow = new FaceServiceClient(properties(stub.baseUrl(), 1000, 1000),
                new ObjectMapper());
        assertThatThrownBy(() -> slow.extract(SYNTHETIC_IMAGE))
                .isInstanceOf(FaceServiceException.class)
                .satisfies(thrown -> assertThat(((FaceServiceException) thrown).kind())
                        .isEqualTo(FaceServiceFailureKind.DEPENDENCY));
    }
}

package cn.yuanxin.mvp.web.face;

import cn.yuanxin.mvp.web.auth.FaceClassification;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link InsightFaceProvider} 映射测试（红线 1）：成功检出人脸**绝不**是
 * {@code MATCHED}/{@code RELIABLE_NEW}。含判别力负向断言。
 */
class InsightFaceProviderTest {

    private static final byte[] SYNTHETIC_IMAGE = "fake-face-bytes".getBytes(StandardCharsets.UTF_8);

    private FaceServiceStub stub;
    private InsightFaceProvider provider;

    @BeforeEach
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        InsightFaceProperties props = new InsightFaceProperties(stub.baseUrl(), "openvela-mvp",
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, null);
        provider = new InsightFaceProvider(new FaceServiceClient(props, new ObjectMapper()));
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("红线1：extract 成功检出人脸 → UNCERTAIN，且绝不是 MATCHED/RELIABLE_NEW")
    void extractSuccessIsUncertainNeverMatched() {
        FaceClassification result = provider.classify("grant", SYNTHETIC_IMAGE);
        assertThat(result).isEqualTo(FaceClassification.UNCERTAIN);
        assertThat(result).isNotEqualTo(FaceClassification.MATCHED);
        assertThat(result).isNotEqualTo(FaceClassification.RELIABLE_NEW);
    }

    @Test
    @DisplayName("NO_FACE → QUALITY_REJECTED")
    void noFaceIsQualityRejected() {
        stub.extract(400, FaceServiceStub.errorBody("NO_FACE", false, "r1"));
        assertThat(provider.classify("grant", SYNTHETIC_IMAGE))
                .isEqualTo(FaceClassification.QUALITY_REJECTED);
    }

    @Test
    @DisplayName("MULTI_FACES_AMBIGUOUS → QUALITY_REJECTED")
    void multiFacesIsQualityRejected() {
        stub.extract(400, FaceServiceStub.errorBody("MULTI_FACES_AMBIGUOUS", false, "r2"));
        assertThat(provider.classify("grant", SYNTHETIC_IMAGE))
                .isEqualTo(FaceClassification.QUALITY_REJECTED);
    }

    @Test
    @DisplayName("503 → DEPENDENCY_FAILED（绝不视为匹配）")
    void serviceUnavailableIsDependencyFailed() {
        stub.extract(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r3"));
        FaceClassification result = provider.classify("grant", SYNTHETIC_IMAGE);
        assertThat(result).isEqualTo(FaceClassification.DEPENDENCY_FAILED);
        assertThat(result).isNotEqualTo(FaceClassification.MATCHED);
    }

    @Test
    @DisplayName("401（配置错误）→ DEPENDENCY_FAILED，不静默成功")
    void unauthorizedIsNotSuccess() {
        stub.extract(401, FaceServiceStub.errorBody("UNAUTHORIZED", false, "r4"));
        FaceClassification result = provider.classify("grant", SYNTHETIC_IMAGE);
        assertThat(result).isNotEqualTo(FaceClassification.MATCHED);
        assertThat(result).isNotEqualTo(FaceClassification.RELIABLE_NEW);
        assertThat(result).isEqualTo(FaceClassification.DEPENDENCY_FAILED);
    }

    @Test
    @DisplayName("判别力：任何 classify 结果都不可能是 MATCHED/RELIABLE_NEW")
    void classifyNeverReturnsMatchedOrReliableNew() {
        stub.extract(200, "{\"face_count\":1,\"request_id\":\"ok\"}");
        assertThat(provider.classify("grant", SYNTHETIC_IMAGE))
                .isNotIn(FaceClassification.MATCHED, FaceClassification.RELIABLE_NEW);
        stub.extract(503, FaceServiceStub.errorBody("INFERENCE_TIMEOUT", true, "r5"));
        assertThat(provider.classify("grant", SYNTHETIC_IMAGE))
                .isNotIn(FaceClassification.MATCHED, FaceClassification.RELIABLE_NEW);
    }
}

package cn.yuanxin.mvp.web.face;

import cn.yuanxin.mvp.web.care.CareFaceVerifier;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/** {@link InsightFaceCareVerifier} 1:1 映射测试（红线：绝不用全库 top1、绝不默认 MATCHED）。 */
class InsightFaceCareVerifierTest {

    private static final byte[] SYNTHETIC_FACE = "fake-face-bytes".getBytes(StandardCharsets.UTF_8);
    private static final UUID MEMBER_ID = UUID.fromString("00000000-0000-0000-0000-0000000000aa");

    private FaceServiceStub stub;
    private JdbcTemplate jdbc;
    private InsightFaceCareVerifier verifier;

    @BeforeEach
    @SuppressWarnings("unchecked")
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        jdbc = mock(JdbcTemplate.class);
        when(jdbc.query(anyString(), any(RowMapper.class), any()))
                .thenReturn(List.of(new InsightFaceCareVerifier.MemberRef("openvela-mvp", "subj-1")));
        InsightFaceProperties props = new InsightFaceProperties(stub.baseUrl(), "openvela-mvp",
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, 0.4);
        verifier = new InsightFaceCareVerifier(new FaceServiceClient(props, new ObjectMapper()),
                jdbc, props.verifyThreshold());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("verify matched=true → MATCHED，且请求带 namespace/subject_id")
    void matchedIsMatched() {
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.MATCHED);
        String body = new String(stub.last("POST", "/v1/verify").body(), StandardCharsets.UTF_8);
        assertThat(body).contains("openvela-mvp").contains("subj-1");
    }

    @Test
    @DisplayName("verify matched=false → MISMATCH（不默认 MATCHED）")
    void notMatchedIsMismatch() {
        stub.verify(200, "{\"matched\":false,\"similarity\":0.1,\"threshold\":0.4,"
                + "\"request_id\":\"r-mismatch\"}");
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.MISMATCH);
    }

    @Test
    @DisplayName("SUBJECT_NOT_FOUND → CAPABILITY_UNAVAILABLE（无绑定即 fail-closed）")
    void subjectNotFoundIsCapabilityUnavailable() {
        stub.verify(404, FaceServiceStub.errorBody("SUBJECT_NOT_FOUND", false, "r-sub"));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
    }

    @Test
    @DisplayName("LIVENESS_UNSUPPORTED → CAPABILITY_UNAVAILABLE")
    void livenessUnsupportedIsCapabilityUnavailable() {
        stub.verify(501, FaceServiceStub.errorBody("LIVENESS_UNSUPPORTED", false, "r-live"));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
    }

    @Test
    @DisplayName("NO_FACE → QUALITY_REJECTED")
    void noFaceIsQualityRejected() {
        stub.verify(400, FaceServiceStub.errorBody("NO_FACE", false, "r-nf"));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.QUALITY_REJECTED);
    }

    @Test
    @DisplayName("5xx → DEPENDENCY_FAILED")
    void serverErrorIsDependencyFailed() {
        stub.verify(503, FaceServiceStub.errorBody("MODEL_UNAVAILABLE", true, "r-dep"));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.DEPENDENCY_FAILED);
    }

    @Test
    @DisplayName("成员无 face_subject_ref / 不存在 → CAPABILITY_UNAVAILABLE（不调远端）")
    @SuppressWarnings("unchecked")
    void missingMemberBindingIsCapabilityUnavailable() {
        when(jdbc.query(anyString(), any(RowMapper.class), any())).thenReturn(List.of());
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
        assertThat(stub.requests()).isEmpty();

        when(jdbc.query(anyString(), any(RowMapper.class), any()))
                .thenReturn(List.of(new InsightFaceCareVerifier.MemberRef("openvela-mvp", "  ")));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
    }
}

